def _install_security() -> None:
    tenant_tables = [
        'artwork_passports', 'collection_records', 'engine_cases', 'provenance_events',
        'agent_runs', 'collection_relationships', 'condition_inspections', 'copyright_matches',
        'evidence_documents', 'human_reviews', 'market_comparables', 'report_versions',
        'shipments', 'valuation_reports', 'custody_events', 'damage_findings',
        'evidence_chunks', 'evidence_claims', 'tool_executions',
    ]
    tables_sql = ', '.join(f'vernis.{table}' for table in tenant_tables)
    op.execute(f'revoke all on {tables_sql} from anon, authenticated')
    op.execute(f'grant select on {tables_sql} to authenticated')
    for table in tenant_tables:
        op.execute(f'alter table vernis.{table} enable row level security')
        op.execute(f'alter table vernis.{table} force row level security')
        if table == 'evidence_documents':
            predicate = "vernis_private.is_org_member(organization_id, null) and (sensitivity <> 'restricted' or vernis_private.is_org_member(organization_id, array['owner','administrator','investigator','reviewer']))"
        elif table == 'evidence_chunks':
            predicate = "vernis_private.is_org_member(organization_id, null) and exists (select 1 from vernis.evidence_documents d where d.id = evidence_chunks.evidence_document_id and d.organization_id = evidence_chunks.organization_id and (d.sensitivity <> 'restricted' or vernis_private.is_org_member(evidence_chunks.organization_id, array['owner','administrator','investigator','reviewer'])))"
        else:
            predicate = 'vernis_private.is_org_member(organization_id, null)'
        op.execute(
            f'create policy {table}_select_member on vernis.{table} for select to authenticated using ({predicate})'
        )

    # Registry/evaluation records are readable but never client-writable.
    op.execute('revoke all on vernis.model_versions, vernis.evaluation_runs from anon, authenticated')
    op.execute('grant select on vernis.model_versions, vernis.evaluation_runs to authenticated')
    for table in ['model_versions', 'evaluation_runs']:
        op.execute(f'alter table vernis.{table} enable row level security')
        op.execute(f'alter table vernis.{table} force row level security')
        op.execute(f'create policy {table}_select_authenticated on vernis.{table} for select to authenticated using (true)')

    # Upload intents are server-only and still receive RLS defense in depth.
    op.execute('revoke all on vernis.upload_intents from anon, authenticated')
    op.execute('alter table vernis.upload_intents enable row level security')
    op.execute('alter table vernis.upload_intents force row level security')


